require_once __DIR__ . '/config_medical.php';medical_require_login();if($_SERVER['REQUEST_METHOD']!=='POST'||!medical_verify_csrf(isset($_POST['csrf_token'])?$_POST['csrf_token']:'')){http_response_code(400);die('Bad Request');}$id=(int)$_POST['id'];$row=medical_get_request($id);$u=medical_current_user();if(!$row||(int)$row['user_id']!==(int)$u['id']||in_array($row['status'],array('completed','cancelled'),true)){http_response_code(403);die('ไม่สามารถยกเลิกรายการนี้ได้');}$old=$row['status'];$stmt=$conn->prepare("UPDATE medical_repair_requests SET status='cancelled' WHERE id=?");$stmt->bind_param('i',$id);$stmt->execute();$stmt->close();medical_log($id,'cancel',$old,'cancelled','ผู้แจ้งยกเลิกรายการ');medical_send_line("🩺 ยกเลิกงานซ่อมเครื่องมือแพทย์\nเลขที่: {$row['request_no']}\nเครื่องมือ: {$row['equipment_name']}\nผู้แจ้ง: {$row['requester_name']}",'medical_repair_cancelled');medical_flash('success','ยกเลิกรายการเรียบร้อยแล้ว');header('Location:detail.php?id='.$id);exit;
